<?php

class Solution {

    /**
     * @param Integer[] $salary
     * @return Float
     */
    function average($salary) {
        $min = PHP_INT_MAX;
        $max = PHP_INT_MIN;
        $sum = 0;

        foreach ($salary as $s) {
            $sum += $s;
            if ($s < $min) $min = $s;
            if ($s > $max) $max = $s;
        }

        return ($sum - $min - $max) / (count($salary) - 2);
    }
}
?>
