class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Boolean
     */
    function kLengthApart($nums, $k) {
        $last = -1;
        $n = count($nums);

        for ($i = 0; $i < $n; $i++) {
            if ($nums[$i] == 1) {
                if ($last != -1 && $i - $last - 1 < $k) {
                    return false;
                }
                $last = $i;
            }
        }

        return true;
    }
}
