class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function ambiguousCoordinates($s) {
        $n = strlen($s);
        $digits = substr($s, 1, $n - 2);
        $len = strlen($digits);
        $res = [];

        for ($i = 1; $i < $len; $i++) {
            $left = substr($digits, 0, $i);
            $right = substr($digits, $i);

            $leftParts = $this->buildNumbers($left);
            $rightParts = $this->buildNumbers($right);

            foreach ($leftParts as $l) {
                foreach ($rightParts as $r) {
                    $res[] = "(" . $l . ", " . $r . ")";
                }
            }
        }

        return $res;
    }

    private function buildNumbers($s) {
        $n = strlen($s);
        $ans = [];

        if ($n == 1 || $s[0] != '0') {
            $ans[] = $s;
        }

        for ($i = 1; $i < $n; $i++) {
            $intPart = substr($s, 0, $i);
            $fracPart = substr($s, $i);

            if (($intPart[0] == '0' && strlen($intPart) > 1) || $fracPart[strlen($fracPart) - 1] == '0') {
                continue;
            }

            $ans[] = $intPart . "." . $fracPart;
        }

        return $ans;
    }
}
