<?php
class Solution {

    /**
     * @param Integer[][] $grid
     * @param Integer[][] $hits
     * @return Integer[]
     */
    function hitBricks($grid, $hits) {
        $m = count($grid);
        $n = count($grid[0]);
        $top = $m * $n;
        $parent = [];
        $size = [];
        $total = $m * $n + 1;

        for ($i = 0; $i < $total; $i++) {
            $parent[$i] = $i;
            $size[$i] = 1;
        }

        $find = function($x) use (&$parent, &$find) {
            if ($parent[$x] !== $x) {
                $parent[$x] = $find($parent[$x]);
            }
            return $parent[$x];
        };

        $union = function($a, $b) use (&$parent, &$size, &$find) {
            $ra = $find($a);
            $rb = $find($b);
            if ($ra === $rb) return;
            if ($size[$ra] < $size[$rb]) {
                $tmp = $ra; $ra = $rb; $rb = $tmp;
            }
            $parent[$rb] = $ra;
            $size[$ra] += $size[$rb];
        };

        // Remove hit bricks first
        $copy = $grid;
        $k = count($hits);
        for ($i = 0; $i < $k; $i++) {
            $r = $hits[$i][0];
            $c = $hits[$i][1];
            if ($copy[$r][$c] == 1) {
                $copy[$r][$c] = 0;
            }
        }

        $dirs = [[1,0],[-1,0],[0,1],[0,-1]];

        // Build DSU from remaining bricks
        for ($r = 0; $r < $m; $r++) {
            for ($c = 0; $c < $n; $c++) {
                if ($copy[$r][$c] == 0) continue;
                $id = $r * $n + $c;
                if ($r == 0) {
                    $union($id, $top);
                }
                if ($r > 0 && $copy[$r - 1][$c] == 1) {
                    $union($id, ($r - 1) * $n + $c);
                }
                if ($c > 0 && $copy[$r][$c - 1] == 1) {
                    $union($id, $r * $n + $c - 1);
                }
            }
        }

        $ans = array_fill(0, $k, 0);

        for ($i = $k - 1; $i >= 0; $i--) {
            $r = $hits[$i][0];
            $c = $hits[$i][1];
            if ($grid[$r][$c] == 0) {
                $ans[$i] = 0;
                continue;
            }

            $before = $size[$find($top)];
            $id = $r * $n + $c;
            $copy[$r][$c] = 1;

            if ($r == 0) {
                $union($id, $top);
            }

            foreach ($dirs as $d) {
                $nr = $r + $d[0];
                $nc = $c + $d[1];
                if ($nr >= 0 && $nr < $m && $nc >= 0 && $nc < $n && $copy[$nr][$nc] == 1) {
                    $union($id, $nr * $n + $nc);
                }
            }

            $after = $size[$find($top)];
            $ans[$i] = max(0, $after - $before - 1);
        }

        return $ans;
    }
}
?>
