class Solution {

    /**
     * @param String $s
     * @return Boolean
     */
    function areOccurrencesEqual($s) {
        $freq = array_fill(0, 26, 0);
        $n = strlen($s);

        for ($i = 0; $i < $n; $i++) {
            $freq[ord($s[$i]) - 97]++;
        }

        $target = 0;
        for ($i = 0; $i < 26; $i++) {
            if ($freq[$i] > 0) {
                if ($target === 0) {
                    $target = $freq[$i];
                } elseif ($freq[$i] !== $target) {
                    return false;
                }
            }
        }

        return true;
    }
}
