class Solution {

    /**
     * @param Integer[] $arr
     * @return Integer
     */
    function numFactoredBinaryTrees($arr) {
        $MOD = 1000000007;
        sort($arr);
        $n = count($arr);
        $dp = array_fill(0, $n, 1);

        $index = [];
        for ($i = 0; $i < $n; $i++) {
            $index[$arr[$i]] = $i;
        }

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $i; $j++) {
                if ($arr[$i] % $arr[$j] === 0) {
                    $right = intdiv($arr[$i], $arr[$j]);
                    if (isset($index[$right])) {
                        $k = $index[$right];
                        $dp[$i] = ($dp[$i] + ($dp[$j] * $dp[$k]) % $MOD) % $MOD;
                    }
                }
            }
        }

        $ans = 0;
        for ($i = 0; $i < $n; $i++) {
            $ans = ($ans + $dp[$i]) % $MOD;
        }
        return $ans;
    }
}
