     * @param Integer $n
     * @return Integer
     */
    function countVowelPermutation($n) {
        $MOD = 1000000007;

        $a = $e = $i = $o = $u = 1;

        for ($len = 2; $len <= $n; $len++) {
            $na = (($e + $i) % $MOD + $u) % $MOD;
            $ne = ($a + $i) % $MOD;
            $ni = ($e + $o) % $MOD;
            $no = $i;
            $nu = ($i + $o) % $MOD;

            $a = $na;
            $e = $ne;
            $i = $ni;
            $o = $no;
            $u = $nu;
        }

        return ($a + $e + $i + $o + $u) % $MOD;
    }
}
