     * @param Integer $numSlots
     * @return Integer
     */
    function maximumANDSum($nums, $numSlots) {
        $n = count($nums);
        $m = 2 * $numSlots;
        $size = 1 << $m;

        $dp = array_fill(0, $size, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $size; $mask++) {
            if ($dp[$mask] < 0) continue;
            $used = 0;
            for ($i = 0; $i < $m; $i++) {
                if (($mask >> $i) & 1) $used++;
            }
            if ($used >= $n) continue;

            $num = $nums[$used];
            for ($i = 0; $i < $m; $i++) {
                if ((($mask >> $i) & 1) == 0) {
                    $slot = intdiv($i, 2) + 1;
                    $nmask = $mask | (1 << $i);
                    $val = $dp[$mask] + ($num & $slot);
                    if ($val > $dp[$nmask]) $dp[$nmask] = $val;
                }
            }
        }

        return max($dp);
    }
