class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function numOfWays($nums) {
        $n = count($nums);
        $MOD = 1000000007;

        // Pascal triangle for combinations up to 1000
        $C = array_fill(0, $n + 1, array_fill(0, $n + 1, 0));
        for ($i = 0; $i <= $n; $i++) {
            $C[$i][0] = 1;
            $C[$i][$i] = 1;
            for ($j = 1; $j < $i; $j++) {
                $C[$i][$j] = ($C[$i - 1][$j - 1] + $C[$i - 1][$j]) % $MOD;
            }
        }

        $dfs = function($arr) use (&$dfs, $C, $MOD) {
            $len = count($arr);
            if ($len <= 2) return 1;

            $root = $arr[0];
            $left = [];
            $right = [];
            for ($i = 1; $i < $len; $i++) {
                if ($arr[$i] < $root) $left[] = $arr[$i];
                else $right[] = $arr[$i];
            }

            $l = $dfs($left);
            $r = $dfs($right);
            $ways = $C[$len - 1][count($left)];
            $ways = ($ways * $l) % $MOD;
            $ways = ($ways * $r) % $MOD;
            return $ways;
        };

        $ans = $dfs($nums) - 1;
        if ($ans < 0) $ans += $MOD;
        return $ans;
    }
}
