class Solution {

    /**
     * @param Integer $n
     * @param Integer[][] $restrictions
     * @param Integer[][] $requests
     * @return Boolean[]
     */
    function friendRequests($n, $restrictions, $requests) {
        $parent = range(0, $n - 1);
        $rank = array_fill(0, $n, 0);

        $find = function($x) use (&$parent, &$find) {
            if ($parent[$x] !== $x) {
                $parent[$x] = $find($parent[$x]);
            }
            return $parent[$x];
        };

        $union = function($a, $b) use (&$parent, &$rank, &$find) {
            $ra = $find($a);
            $rb = $find($b);
            if ($ra === $rb) return;
            if ($rank[$ra] < $rank[$rb]) {
                $parent[$ra] = $rb;
            } elseif ($rank[$ra] > $rank[$rb]) {
                $parent[$rb] = $ra;
            } else {
                $parent[$rb] = $ra;
                $rank[$ra]++;
            }
        };

        $res = [];
        foreach ($requests as $req) {
            $u = $req[0];
            $v = $req[1];
            $ru = $find($u);
            $rv = $find($v);

            if ($ru === $rv) {
                $res[] = true;
                continue;
            }

            $ok = true;
            foreach ($restrictions as $r) {
                $x = $r[0];
                $y = $r[1];
                $rx = $find($x);
                $ry = $find($y);
                if (($ru === $rx && $rv === $ry) || ($ru === $ry && $rv === $rx)) {
                    $ok = false;
                    break;
                }
            }

            if ($ok) {
                $union($ru, $rv);
                $res[] = true;
            } else {
                $res[] = false;
            }
        }

        return $res;
    }
}
