    /**
     * @param String $s1
     * @param String $s2
     * @return Boolean
     */
    function isScramble($s1, $s2) {
        $n = strlen($s1);
        if ($n !== strlen($s2)) return false;
        if ($s1 === $s2) return true;

        $memo = [];

        $dfs = function($a, $b) use (&$dfs, &$memo) {
            $key = $a . '#' . $b;
            if (isset($memo[$key])) return $memo[$key];

            if ($a === $b) return $memo[$key] = true;

            $len = strlen($a);
            if ($len !== strlen($b)) return $memo[$key] = false;

            $cnt = array_fill(0, 26, 0);
            for ($i = 0; $i < $len; $i++) {
                $cnt[ord($a[$i]) - 97]++;
                $cnt[ord($b[$i]) - 97]--;
            }
            for ($i = 0; $i < 26; $i++) {
                if ($cnt[$i] !== 0) return $memo[$key] = false;
            }

            for ($i = 1; $i < $len; $i++) {
                $a1 = substr($a, 0, $i);
                $a2 = substr($a, $i);

                // No swap
                if ($dfs($a1, substr($b, 0, $i)) && $dfs($a2, substr($b, $i))) {
                    return $memo[$key] = true;
                }
                // Swap
                if ($dfs($a1, substr($b, $len - $i)) && $dfs($a2, substr($b, 0, $len - $i))) {
                    return $memo[$key] = true;
                }
            }

            return $memo[$key] = false;
        };

        return $dfs($s1, $s2);
    }
}
