    /**
     * @param Integer[] $nums1
     * @param Integer[] $nums2
     * @return Integer
     */
    function numTriplets($nums1, $nums2) {
        return $this->countPairs($nums1, $nums2) + $this->countPairs($nums2, $nums1);
    }

    private function countPairs($a, $b) {
        $freq = [];
        foreach ($b as $x) {
            if (!isset($freq[$x])) $freq[$x] = 0;
            $freq[$x]++;
        }

        $ans = 0;
        $n = count($a);

        for ($i = 0; $i < $n; $i++) {
            $target = $a[$i] * $a[$i];
            foreach ($freq as $val => $cntVal) {
                if ($target % $val != 0) continue;
                $other = intdiv($target, $val);
                if (!isset($freq[$other])) continue;

                if ($val < $other) {
                    $ans += $cntVal * $freq[$other];
                } elseif ($val == $other) {
                    $ans += intdiv($cntVal * ($cntVal - 1), 2);
                }
            }
        }

        return $ans;
    }
}
