class DualHeap {
    private $small = [];
    private $large = [];
    private $delayed = [];
    private $smallSize = 0;
    private $largeSize = 0;
    private $k;

    public function __construct($k) {
        $this->k = $k;
    }

    private function topSmall() {
        while (!empty($this->small)) {
            $top = $this->small[0];
            if (isset($this->delayed[$top])) {
                $this->eraseDelayed($top);
                $this->popHeap($this->small, function($a, $b) { return $a > $b; });
            } else {
                return $top;
            }
        }
        return null;
    }

    private function topLarge() {
        while (!empty($this->large)) {
            $top = $this->large[0];
            if (isset($this->delayed[$top])) {
                $this->eraseDelayed($top);
                $this->popHeap($this->large, function($a, $b) { return $a < $b; });
            } else {
                return $top;
            }
        }
        return null;
    }

    private function eraseDelayed($num) {
        $this->delayed[$num]--;
        if ($this->delayed[$num] === 0) unset($this->delayed[$num]);
    }

    private function pushHeap(&$heap, $num, $cmp) {
        $heap[] = $num;
        $i = count($heap) - 1;
        while ($i > 0) {
            $p = intdiv($i - 1, 2);
            if ($cmp($heap[$i], $heap[$p])) {
                $tmp = $heap[$i];
                $heap[$i] = $heap[$p];
                $heap[$p] = $tmp;
                $i = $p;
            } else break;
        }
    }

    private function popHeap(&$heap, $cmp) {
        $n = count($heap);
        if ($n === 0) return;
        $last = array_pop($heap);
        if ($n === 1) return;
        $heap[0] = $last;
        $i = 0;
        while (true) {
            $l = $i * 2 + 1;
            $r = $i * 2 + 2;
            $best = $i;
            if ($l < count($heap) && $cmp($heap[$l], $heap[$best])) $best = $l;
            if ($r < count($heap) && $cmp($heap[$r], $heap[$best])) $best = $r;
            if ($best === $i) break;
            $tmp = $heap[$i];
            $heap[$i] = $heap[$best];
            $heap[$best] = $tmp;
            $i = $best;
        }
