            $p = intdiv($i - 1, 2);
            if ($cmp($heap[$i], $heap[$p])) {
                $tmp = $heap[$i];
                $heap[$i] = $heap[$p];
                $heap[$p] = $tmp;
                $i = $p;
            } else break;
        }
    }

    private function popHeap(&$heap, $cmp) {
