class Solution {

    /**
     * @param Integer $rows
     * @param Integer $cols
     * @param Integer $rStart
     * @param Integer $cStart
     * @return Integer[][]
     */
    function spiralMatrixIII($rows, $cols, $rStart, $cStart) {
        $res = [];
        $r = $rStart;
        $c = $cStart;
        $res[] = [$r, $c];

        $dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // east, south, west, north
        $step = 1;
        $dir = 0;

        while (count($res) < $rows * $cols) {
            for ($t = 0; $t < 2; $t++) {
                for ($i = 0; $i < $step; $i++) {
                    $r += $dirs[$dir][0];
                    $c += $dirs[$dir][1];
                    if ($r >= 0 && $r < $rows && $c >= 0 && $c < $cols) {
                        $res[] = [$r, $c];
                        if (count($res) == $rows * $cols) {
                            return $res;
                        }
                    }
                }
                $dir = ($dir + 1) % 4;
            }
            $step++;
        }

        return $res;
    }
}
