<?php

class Solution {

    /**
     * @param String $s1
     * @param String $s2
     * @return String[]
     */
    function uncommonFromSentences($s1, $s2) {
        $cnt = [];

        foreach (explode(' ', $s1) as $w) {
            if (!isset($cnt[$w])) $cnt[$w] = 0;
            $cnt[$w]++;
        }

        foreach (explode(' ', $s2) as $w) {
            if (!isset($cnt[$w])) $cnt[$w] = 0;
            $cnt[$w]++;
        }

        $ans = [];
        foreach ($cnt as $word => $c) {
            if ($c === 1) $ans[] = $word;
        }

        return $ans;
    }
}
?>
