        if ($root === -1) return false;

        $visited = array_fill(0, $n, false);
        $queue = [$root];
        $head = 0;
        $count = 0;

        while ($head < count($queue)) {
            $node = $queue[$head++];
            if ($visited[$node]) return false;
            $visited[$node] = true;
            $count++;

            $l = $leftChild[$node];
            if ($l !== -1) $queue[] = $l;

            $r = $rightChild[$node];
            if ($r !== -1) $queue[] = $r;
        }

        return $count === $n;
    }
}
